def is_nested(string):
    '''
    Create a function that takes a string as input which contains only square brackets.
    The function should return True if and only if there is a valid subsequence of brackets 
    where at least one bracket in the subsequence is nested.

    is_nested('[[]]') ➞ True
    is_nested('[]]]]]]][[[[[]') ➞ False
    is_nested('[][]') ➞ False
    is_nested('[]') ➞ False
    is_nested('[[][]]') ➞ True
    is_nested('[[]][[') ➞ True
    '''
    def is_valid_bracket_sequence(s):
        count = 0
        for char in s:
            if char == '[':
                count += 1
            elif char == ']':
                count -= 1
                if count < 0:
                    return False
        return count == 0

    def has_nesting(s):
        stack = []
        for char in s:
            if char == '[':
                stack.append(char)
            elif char == ']':
                if stack:
                    stack.pop()
        return len(stack) == 0

    # Check if there exists a valid subsequence with nesting
    # We can use dynamic programming or greedy approach

    # Simple approach: check if we can form a valid sequence with nesting
    # by tracking max nesting depth during validation

    def check_with_nesting():
        # Use a stack to track nesting
        stack = []
        max_depth = 0

        for char in string:
            if char == '[':
                stack.append(char)
                max_depth = max(max_depth, len(stack))
            elif char == ']':
                if stack:
                    stack.pop()

        # Valid sequence with nesting if stack is empty and max_depth > 1
        return len(stack) == 0 and max_depth > 1

